from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)

        rank = (event.get('revision', 0), position)
        previous = winners.get(key)
        if previous is None or rank > previous[0]:
            winners[key] = (rank, event)

    balances = dict(data.get('opening', {}))
    rounding = data['rounding']

    for _, event in winners.values():
        if event.get('void', False):
            continue

        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances.setdefault(key, 0)
        balances[key] += amount(event, rounding)

    return {'balances': balances}

def _round_scaled(numerator, mode):
    if mode == 'half_up':
        return (numerator + 5000) // 10000
    return numerator // 10000


def amount(event, mode):
    price_quantity = event['price'] * event.get('quantity', 1)
    discount_bp = min(10000, max(0, event.get('discount_bp', 0)))

    net = _round_scaled(price_quantity * (10000 - discount_bp), mode)
    tax = _round_scaled(net * event.get('tax_bp', 0), mode)
    total = net + tax

    if event.get('kind') == 'refund':
        return -total
    return total
